-- Fecha de la última verificación de los datos de cada festival en su web oficial
alter table festivals add column if not exists last_verified_at date;

-- Ampliación de la base: 180 festivales, premios y mercados verificados el 2026-10-09
-- No se insertan los que ya existan con el mismo nombre
insert into festivals (name, country, city, tier, month, deadline, submission_fee, platform, url, genres, accepts_types, prestige, reason, last_verified_at)
select v.* from (values
('DOK Leipzig', 'Alemania', 'Leipzig', 'tier_b', 'Octubre-Noviembre', 'Febrero-Julio', '35-60€ (+IVA)', 'Directo', 'https://www.dok-leipzig.de/en', array['documental_social','documental_historico','experimental','animacion']::text[], array['documental','cortometraje','mediometraje','largometraje']::text[], 78, 'Referencia europea para documental de autor y animación de todas las duraciones. La competición internacional de documental exige al menos estreno europeo (preferible mundial o internacional); los cortos de hasta 40 min y la animación, al menos estreno en Alemania.', date '2026-10-09'),
('Thessaloniki Documentary Festival', 'Grecia', 'Tesalónica', 'tier_b', 'Marzo', 'Julio-Noviembre', '40-60€', 'Directo', 'https://www.filmfestival.gr/en/', array['documental_social','documental_historico','experimental']::text[], array['documental','mediometraje','largometraje']::text[], 72, 'Largos documentales (más de 70 min en la competición principal), óperas primas y segundas obras (Newcomers) y documental experimental (Film Forward). Exige estreno mundial, internacional o europeo, sin pase previo en Grecia; el Golden Alexander clasifica para los Oscar.', date '2026-10-09'),
('Cinéma du Réel (París)', 'Francia', 'París', 'tier_b', 'Marzo', 'Septiembre-Noviembre', '15-50€', 'Directo', 'https://www.cinemadureel.org/en/', array['documental_social','documental_historico','experimental']::text[], array['documental','cortometraje','mediometraje','largometraje']::text[], 76, 'Documental de creación y cine de lo real de cualquier duración. La selección internacional exige estreno en Francia y la francesa, estreno mundial; las películas deben haberse terminado después de mediados de enero del año anterior.', date '2026-10-09'),
('Doclisboa', 'Portugal', 'Lisboa', 'tier_b', 'Octubre', 'Febrero-Mayo', '15-50€', 'Directo', 'https://www.doclisboa.org/en/', array['documental_social','documental_historico','experimental']::text[], array['documental','cortometraje','mediometraje','largometraje']::text[], 72, 'Cine documental de autor y formas híbridas, de cualquier duración. Exige que la película sea inédita en Portugal (cine, TV o streaming) y prefiere estrenos mundiales, internacionales o europeos; la sección Green Years, para óperas primas europeas, exige estreno mundial, internacional o europeo.', date '2026-10-09'),
('DokuFest (Prizren)', 'Kosovo', 'Prizren', 'tier_c', 'Agosto', 'Noviembre-Marzo', '9-35€', 'FilmFreeway', 'https://dokufest.com/en', array['documental_social','documental_historico','experimental','animacion']::text[], array['documental','cortometraje','largometraje']::text[], 64, 'Festival de documental y cortometraje con mucho ambiente. Admite largos documentales sin límite de duración, cortos documentales de hasta 45 min y cortos de ficción de hasta 30 min, terminados después del 1 de enero del año anterior. Las fuentes consultadas no publican un requisito estricto de estreno: hay que consultar las bases.', date '2026-10-09'),
('Ji.hlava IDFF', 'Chequia', 'Jihlava', 'tier_b', 'Octubre-Noviembre', 'Enero-Junio', '25€', 'Directo', 'https://www.ji-hlava.com', array['documental_social','documental_historico','experimental']::text[], array['documental','cortometraje','mediometraje','largometraje']::text[], 74, 'El mayor festival de documental de Europa central y del este, con fuerte apuesta por el documental experimental y de autor. Prefiere estrenos mundiales, internacionales o europeos; los plazos dependen de si la película ya se ha estrenado (en junio solo montajes provisionales e inéditos).', date '2026-10-09'),
('Docaviv (Tel Aviv)', 'Israel', 'Tel Aviv', 'tier_c', 'Mayo-Junio', 'Hasta Enero', '15-25€', 'Directo', 'https://www.docaviv.co.il', array['documental_social','documental_historico']::text[], array['documental','cortometraje','largometraje']::text[], 62, 'Principal festival de documental de Israel; la competición internacional es para largos de más de 40 min. Exige estreno en Israel: la película no puede haberse proyectado, emitido ni estado disponible online allí.', date '2026-10-09'),
('Millennium Docs Against Gravity (Varsovia)', 'Polonia', 'Varsovia', 'tier_c', 'Mayo', 'Hasta Enero', '20€', 'Directo', 'https://mdag.pl', array['documental_social','documental_historico','biopic']::text[], array['documental','largometraje']::text[], 66, 'Gran festival de documental en Polonia, de vocación popular, que se celebra en siete ciudades y online; clasifica para los Oscar. La competición exige estreno en Polonia y más de 45 min de duración.', date '2026-10-09'),
('True/False Film Fest (Columbia)', 'Estados Unidos', 'Columbia (Misuri)', 'tier_b', 'Marzo', 'Agosto-Diciembre', '20-95 USD', 'Directo', 'https://truefalse.org', array['documental_social','experimental','documental_historico']::text[], array['documental','cortometraje','largometraje']::text[], 74, 'Festival muy curado de no ficción creativa e híbrida, para largos (40 min o más) y cortos. Las bases consultadas no fijan un requisito de estreno; hay que consultar las bases. Tiene tarifa reducida para estudiantes.', date '2026-10-09'),
('Full Frame Documentary Film Festival (Durham)', 'Estados Unidos', 'Durham (Carolina del Norte)', 'tier_c', 'Abril', 'Agosto-Noviembre', '40-90 USD', 'Directo', 'https://www.fullframefest.org', array['documental_social','documental_historico']::text[], array['documental','cortometraje','largometraje']::text[], 66, 'Festival de referencia del documental en EE. UU., para cortos y largos de hasta 180 min. No tiene requisito formal de estreno, aunque tiene en cuenta la exposición previa, sobre todo los pases en Carolina del Norte.', date '2026-10-09'),
('DOC NYC (Nueva York)', 'Estados Unidos', 'Nueva York', 'tier_b', 'Noviembre', 'Enero-Junio', '50-75 USD', 'FilmFreeway', 'https://docnyc.net', array['documental_social','documental_historico','biopic']::text[], array['documental','cortometraje','largometraje']::text[], 76, 'El mayor festival de documental de EE. UU., con mucha industria y escaparate de cara a los premios. Exige como mínimo estreno en Nueva York y prefiere estrenos mundiales o estadounidenses; las secciones Short List y Winner''s Circle no piden estreno.', date '2026-10-09'),
('Big Sky Documentary Film Festival (Missoula)', 'Estados Unidos', 'Missoula (Montana)', 'tier_c', 'Febrero', 'Mayo-Octubre', '5-50 USD', 'FilmFreeway', 'https://www.bigskyfilmfest.org', array['documental_social','documental_naturaleza','documental_historico']::text[], array['documental','cortometraje','mediometraje','largometraje']::text[], 60, 'Festival de documental de no ficción de todas las duraciones, accesible y cercano con los cineastas. No exige estreno salvo en Montana, aunque da prioridad a obras con poca difusión previa.', date '2026-10-09'),
('Camden International Film Festival', 'Estados Unidos', 'Camden (Maine)', 'tier_c', 'Septiembre', 'Diciembre-Mayo', '25-60 USD', 'FilmFreeway', 'https://pointsnorthinstitute.org', array['documental_social','experimental']::text[], array['documental','cortometraje','largometraje']::text[], 66, 'Festival de documental creativo muy respetado en la industria estadounidense (Points North Institute) que admite montajes provisionales. Según los listados consultados no exige estreno, aunque la mitad de su programa son estrenos mundiales, en EE. UU. o en Norteamérica.', date '2026-10-09'),
('RIDM (Montreal)', 'Canadá', 'Montreal', 'tier_b', 'Noviembre', 'Marzo-Junio', 'Consultar bases', 'Directo', 'https://ridm.ca/en', array['documental_social','documental_historico','experimental']::text[], array['documental','cortometraje','mediometraje','largometraje']::text[], 68, 'Festival de documental de autor de cualquier formato y tema, con mercado propio (Forum RIDM). Exige estreno en Quebec (sin pase, emisión ni difusión online allí) y que la obra se haya producido después del 1 de julio del año anterior.', date '2026-10-09'),
('FIDMarseille (Marsella)', 'Francia', 'Marsella', 'tier_b', 'Julio', 'Noviembre-Marzo', '25-50€', 'Directo', 'https://fidmarseille.org/en/', array['experimental','documental_social','documental_historico']::text[], array['documental','cortometraje','mediometraje','largometraje']::text[], 76, 'Festival de cine de autor arriesgado, en documental y ficción, ideal para propuestas formales y experimentales. Las fuentes consultadas no publican un requisito formal de estreno, pero la mayoría de su competición son estrenos mundiales o internacionales; se admiten obras producidas desde el 1 de enero del año anterior.', date '2026-10-09'),
('ZagrebDox', 'Croacia', 'Zagreb', 'tier_c', 'Abril', 'Junio-Diciembre', 'Consultar bases', 'FilmFreeway', 'https://www.zagrebdox.net/en', array['documental_social','documental_historico']::text[], array['documental','cortometraje','mediometraje','largometraje']::text[], 62, 'Referencia del documental en los Balcanes, con competición internacional y regional; admite todas las duraciones y tiene un premio para cortos de hasta 40 min. La competición exige estreno en Croacia y películas estrenadas después del 1 de enero del año anterior.', date '2026-10-09'),
('Krakow Film Festival (Cracovia)', 'Polonia', 'Cracovia', 'tier_b', 'Mayo-Junio', 'Octubre-Enero', '15-30€', 'FilmFreeway / Directo', 'https://www.krakowfilmfestival.pl/en/', array['documental_social','documental_historico','animacion','experimental']::text[], array['documental','cortometraje','largometraje']::text[], 70, 'Uno de los festivales más antiguos de Europa dedicados al documental, el corto y la animación; la competición internacional de documental es para obras de 50 min o más. Las competiciones internacionales exigen estreno en Polonia y prefieren el estreno mundial.', date '2026-10-09'),
('One World (Praga)', 'Chequia', 'Praga', 'tier_c', 'Marzo', 'Junio-Noviembre', '20-30€', 'Directo', 'https://www.oneworld.cz', array['documental_social','documental_historico']::text[], array['documental','mediometraje','largometraje']::text[], 64, 'Uno de los mayores festivales de documental sobre derechos humanos del mundo; acepta documentales de 40 min o más y proyectos de realidad virtual. No exige estreno y admite películas que ya han pasado por otros festivales, aunque las competiciones prefieren estrenos mundiales o internacionales.', date '2026-10-09'),
('Movies that Matter (La Haya)', 'Países Bajos', 'La Haya', 'tier_c', 'Marzo', 'Junio-Noviembre', '20-35€', 'Directo', 'https://moviesthatmatter.nl/en/', array['documental_social','drama']::text[], array['documental','cortometraje','mediometraje','largometraje']::text[], 60, 'Festival de derechos humanos para documentales y ficción de cualquier duración y de temática social. No exige estreno pero lo valora; excluye películas ya estrenadas en cines o TV de los Países Bajos o disponibles gratis online.', date '2026-10-09'),
('Beldocs (Belgrado)', 'Serbia', 'Belgrado', 'tier_c', 'Mayo', 'Octubre-Enero', '25-35 USD', 'FilmFreeway', 'https://www.beldocs.rs/en/', array['documental_social','documental_historico','experimental']::text[], array['documental','cortometraje','largometraje']::text[], 56, 'Principal festival de documental de Serbia, abierto a documentales e híbridos recientes. Exige como mínimo estreno en Serbia y da preferencia a los estrenos mundiales, internacionales o europeos.', date '2026-10-09'),
('DMZ Docs (Goyang/Paju)', 'Corea del Sur', 'Goyang / Paju', 'tier_c', 'Septiembre', 'Marzo-Abril', 'Gratuito', 'Directo', 'https://www.dmzdocs.com', array['documental_social','documental_historico']::text[], array['documental','largometraje']::text[], 60, 'Festival de documental de temática de paz, convivencia y sociedad; la inscripción es gratuita. La competición internacional es para largos de más de 60 min y exige estreno asiático.', date '2026-10-09'),
('EIDF - EBS International Documentary Festival', 'Corea del Sur', 'Goyang / Seúl', 'tier_c', 'Agosto', 'Marzo-Mayo', 'Gratuito', 'Directo', 'https://www.eidf.co.kr', array['documental_social','documental_naturaleza','documental_historico']::text[], array['documental','cortometraje','largometraje']::text[], 56, 'Festival de la televisión pública coreana EBS que también emite las películas por TV; la inscripción es gratuita y se hace por email. Requiere que la obra no se haya estrenado comercialmente ni emitido en Corea (ediciones anteriores pedían estreno en Corea).', date '2026-10-09'),
('Yamagata IDFF', 'Japón', 'Yamagata', 'tier_b', 'Octubre', 'Septiembre-Abril', '1.000 JPY', 'Directo', 'https://www.yidff.jp', array['documental_social','documental_historico','experimental']::text[], array['documental','largometraje']::text[], 72, 'Festival bienal (años impares) de gran prestigio en Asia, con competición internacional y la sección New Asian Currents. Según ediciones anteriores no admite cortos y exige que la obra no se haya estrenado públicamente en Japón; hay que confirmarlo en las bases de 2027.', date '2026-10-09'),
('Hot Springs Documentary Film Festival', 'Estados Unidos', 'Hot Springs (Arkansas)', 'tier_c', 'Octubre', 'Diciembre-Julio', '50-65 USD', 'FilmFreeway', 'https://www.hsdfi.org', array['documental_social','documental_historico','biopic']::text[], array['documental','cortometraje','largometraje']::text[], 56, 'Uno de los festivales de documental más antiguos de EE. UU.; admite cortos, largos y series documentales. Según los listados consultados exige estreno en EE. UU., y las obras ya disponibles en VOD pueden quedar fuera de competición.', date '2026-10-09'),
('Docudays UA (Kiev)', 'Ucrania', 'Kiev', 'tier_c', 'Junio', 'Agosto-Diciembre', '10-30 USD', 'FilmFreeway', 'https://docudays.ua/eng/', array['documental_social','documental_historico']::text[], array['documental','cortometraje','largometraje']::text[], 54, 'Festival de documental sobre derechos humanos, con competiciones internacionales de largos (DOCU/WORLD) y de cortos (DOCU/SHORT). Ediciones anteriores exigían estreno en Ucrania y excluían títulos ya vistos en competiciones de otros festivales ucranianos.', date '2026-10-09'),
('DOK.fest München (Múnich)', 'Alemania', 'Múnich', 'tier_b', 'Mayo', 'Hasta Diciembre', '40€', 'Directo', 'https://www.dokfest-muenchen.de', array['documental_social','documental_historico','biopic']::text[], array['documental','largometraje']::text[], 70, 'Uno de los grandes festivales de documental de Alemania, para largos de 52 min o más. Las competiciones exigen estreno en Alemania y prefieren el estreno mundial; quedan fuera los títulos ya estrenados en cines o TV alemanes o disponibles gratis online.', date '2026-10-09'),
('Festival dei Popoli (Florencia)', 'Italia', 'Florencia', 'tier_c', 'Octubre-Noviembre', 'Marzo-Julio', '20-30€', 'Directo', 'https://www.festivaldeipopoli.org', array['documental_social','documental_historico','experimental']::text[], array['documental','largometraje']::text[], 66, 'El festival de documental más antiguo de Europa, orientado a largos de más de 60 min. Exige estreno en Italia (sin pases ni difusión online previa allí) y prefiere estrenos mundiales, internacionales o europeos.', date '2026-10-09'),
('É Tudo Verdade / It''s All True (São Paulo)', 'Brasil', 'São Paulo / Río de Janeiro', 'tier_c', 'Abril', 'Agosto-Noviembre', 'Gratuito', 'Directo', 'https://etudoverdade.com.br', array['documental_social','documental_historico','biopic']::text[], array['documental','cortometraje','largometraje']::text[], 66, 'Principal festival de documental de Latinoamérica: inscripción gratuita, cortos de menos de 30 min y largos de más de 60, y sus ganadores optan a los Oscar. Exige solo estreno en Brasil, así que encaja tras un estreno mundial en otro festival.', date '2026-10-09'),
('Docville (Lovaina)', 'Bélgica', 'Lovaina', 'tier_c', 'Marzo', 'Mayo-Noviembre', 'Consultar bases', 'FilmFreeway', 'https://www.docville.be/en/', array['documental_social','documental_historico']::text[], array['documental','largometraje']::text[], 54, 'Festival belga de documental orientado a largos de más de 50 min; el premio internacional clasifica para los Oscar. Las competiciones internacionales exigen estreno en Bélgica.', date '2026-10-09'),
