('Festival Internacional de Cortometrajes de Drama', 'Grecia', 'Drama', 'tier_b', 'Septiembre', 'Enero-Abril', '25-30€', 'FilmFreeway', 'https://www.dramafilmfestival.gr', array['drama','comedia','animacion','documental_social','experimental']::text[], array['cortometraje','documental','mediometraje']::text[], 64, 'Principal festival de cortos de Grecia, con competiciones internacional, de estudiantes y documental (máx. 40 min; documental 30). Califica para los Oscar y los Premios del Cine Europeo (EFA); exige estreno en Grecia.', date '2026-10-09'),
('Cork International Film Festival', 'Irlanda', 'Cork', 'tier_b', 'Noviembre', 'Enero-Julio', 'Consultar bases', 'FilmFreeway', 'https://www.corkfilmfest.org', array['drama','comedia','animacion','documental_social','experimental']::text[], array['cortometraje','documental','mediometraje','largometraje']::text[], 66, 'Festival histórico irlandés con fuerte programa de cortos internacionales y documentales cortos (máx. 40 min). Tres premios califican para los Oscar (corto internacional, irlandés y documental) y nomina un corto a los Premios del Cine Europeo (EFA); sin requisito de estreno publicado.', date '2026-10-09'),
('PÖFF Shorts (Tallin)', 'Estonia', 'Tallin', 'tier_b', 'Noviembre', 'Marzo-Agosto', 'Consultar bases', 'FilmFreeway, Shortfilmdepot', 'https://shorts.poff.ee', array['drama','comedia','animacion','experimental','fantasia','terror']::text[], array['cortometraje','mediometraje']::text[], 64, 'Sección de cortos del Festival Black Nights de Tallin (máx. 45 min). Califica para los Oscar (Grand Prix de acción real y animación) y los BAFTA, y es miembro de la Academia de Cine Europeo; prioriza al menos el estreno en Estonia.', date '2026-10-09'),
('Busan International Short Film Festival (Busan)', 'Corea del Sur', 'Busan', 'tier_b', 'Abril', 'Octubre-Enero', '11-15€', 'Festhome, Shortfilmdepot, FilmFreeway', 'https://www.bisff.org', array['drama','comedia','animacion','documental_social','experimental']::text[], array['cortometraje','documental']::text[], 62, 'Festival de cortometrajes más antiguo de Asia, con competición internacional y coreana. Los Grand Prix califican para los Oscar en acción real y animación; no se publica requisito de estreno obligatorio, solo obras terminadas el año anterior.', date '2026-10-09'),
('Ottawa International Animation Festival', 'Canadá', 'Ottawa', 'tier_b', 'Septiembre', 'Marzo - Mayo', 'Gratuito', 'Directo', 'https://www.animationfestival.ca', array['animacion','experimental','otro']::text[], array['cortometraje','largometraje']::text[], 88, 'Gran referencia norteamericana de la animación de autor: cortos, largos, estudiantes, encargos y series, con envío gratuito por el formulario de Eventival. Su Gran Premio de cortometraje es calificador para el Oscar y no exige estreno: solo hay que informar del estatus.', date '2026-10-09'),
('Animafest Zagreb', 'Croacia', 'Zagreb', 'tier_b', 'Junio', 'Hasta febrero (cortos) / marzo (largos)', 'Gratuito', 'Directo', 'https://animafest.hr', array['animacion','experimental','otro']::text[], array['cortometraje','largometraje']::text[], 87, 'Uno de los festivales de animación más antiguos y prestigiosos de Europa, con competiciones de cortos (hasta 40 min), estudiantes, infantil y largos. La inscripción es gratuita por Filmchief y su Gran Premio de cortometraje califica para el Oscar. Exige obras terminadas en los dos últimos años, sin requisito de estreno publicado.', date '2026-10-09'),
('ITFS Stuttgart (Internationales Trickfilm-Festival)', 'Alemania', 'Stuttgart', 'tier_b', 'Abril - Mayo', 'Septiembre - Noviembre (cortos) / Enero (largos)', '10-15€', 'Directo', 'https://www.itfs.de', array['animacion','experimental','documental_naturaleza','otro']::text[], array['cortometraje','largometraje']::text[], 85, 'Gran festival europeo de animación con competición internacional (cortos de hasta 30 min), estudiantes, infantil, premio de naturaleza y AniMovie para largos. Se inscribe por Shortfilmdepot y el Grand Prix califica para el Oscar. En AniMovie, el largo no puede estar estrenado comercialmente en Alemania.', date '2026-10-09'),
('Anima (Bruselas)', 'Bélgica', 'Bruselas', 'tier_b', 'Febrero', 'Junio - Octubre', 'Gratuito', 'Directo', 'https://animafestival.be', array['animacion','experimental','otro']::text[], array['cortometraje','largometraje']::text[], 78, 'Festival de animación de referencia en el Benelux, con cortos y largos de cualquier técnica. La inscripción es gratuita por su plataforma propia (Festicine), y el Gran Premio de cortometraje es calificador para el Oscar. Pide obras terminadas en los 18 meses anteriores; las bases no publican requisito de estreno.', date '2026-10-09'),
('Animayo (Gran Canaria)', 'España', 'Las Palmas de Gran Canaria', 'nacional', 'Mayo', 'Septiembre - Enero', 'Gratuito', 'Directo', 'https://www.animayo.com', array['animacion','otro']::text[], array['cortometraje']::text[], 72, 'Es el único festival de animación español calificador para el Oscar al mejor cortometraje de animación, tanto en la competición internacional como en la de habla hispana. Ideal para cortos de animación; la inscripción es gratuita en su web y piden obras no presentadas en ediciones anteriores.', date '2026-10-09'),
('Monstra (Lisboa)', 'Portugal', 'Lisboa', 'tier_b', 'Marzo', 'Junio - Octubre (internacional) / Diciembre (cortos portugueses)', 'Consultar bases', 'FilmFreeway', 'https://www.monstrafestival.com', array['animacion','experimental','otro']::text[], array['cortometraje','mediometraje','largometraje']::text[], 75, 'Gran festival de animación del sur de Europa, con competiciones de largos, cortos largos, cortos, supercortos, estudiantes e infantil (Monstrinha). La animación debe ocupar al menos el 60% del metraje y hay que declarar si se usó IA. Piden obras terminadas en los dos últimos años y no presentadas antes.', date '2026-10-09'),
('Fantoche (Baden)', 'Suiza', 'Baden', 'tier_b', 'Septiembre', 'Invierno - Mayo', 'Gratuito', 'FilmFreeway', 'https://www.fantoche.ch', array['animacion','experimental','otro']::text[], array['cortometraje','largometraje']::text[], 80, 'Festival suizo de animación de autor y experimental; acepta cortos de hasta 40 minutos terminados en los dos últimos años. Desde 2025 su mejor film de la competición internacional es calificador para el Oscar. Inscripción gratuita, preferentemente por FilmFreeway.', date '2026-10-09'),
('Animest (Bucarest)', 'Rumanía', 'Bucarest', 'tier_c', 'Octubre', 'Primavera - Julio', 'Gratuito', 'Directo', 'https://www.animest.ro', array['animacion','documental_social','experimental','musical','otro']::text[], array['cortometraje','largometraje','documental']::text[], 68, 'Principal festival de animación de Europa del Este, con competiciones de cortos, largos, anidocs, estudiantes, infantil, videoclip y VR. La inscripción es gratuita por formulario web. Exige estreno en Rumanía y obras terminadas en los dos últimos años.', date '2026-10-09'),
('GLAS Animation Festival', 'Estados Unidos', 'Los Ángeles', 'tier_c', 'Diciembre', 'Mayo - Agosto', 'Gratuito-45 USD', 'FilmFreeway', 'https://www.glasanimation.com', array['animacion','experimental','otro']::text[], array['cortometraje']::text[], 70, 'Festival independiente de animación de autor, nacido en Berkeley y celebrado ahora en Los Ángeles, con cortos narrativos, experimentales, de estudiantes y de encargo. El primer plazo es gratuito y luego cuesta entre 25 y 45 USD. No publica requisito de estreno ni estatus calificador.', date '2026-10-09'),
('New Chitose Airport International Animation Festival', 'Japón', 'Chitose (Hokkaido)', 'tier_c', 'Noviembre', 'Primavera - Julio', 'Gratuito', 'FilmFreeway', 'https://www.airport-anifes.jp/en/', array['animacion','musical','otro']::text[], array['cortometraje','largometraje']::text[], 68, 'Original festival de animación celebrado en la terminal del aeropuerto de Nuevo Chitose, con competiciones de cortos (menos de 30 min), largos, videoclips y piezas de 15/30 segundos para pantallas. Buena ventana a Asia para la animación independiente. No admite obras presentadas en ediciones anteriores.', date '2026-10-09'),
('Premios Quirino de la Animación Iberoamericana', 'España', 'Santa Cruz de Tenerife', 'nacional', 'Abril', 'Otoño - 1 de diciembre', 'Consultar bases', 'Festhome', 'https://premiosquirino.org', array['animacion','musical','otro']::text[], array['cortometraje','largometraje']::text[], 74, 'Premios de referencia de la animación iberoamericana, con categorías de largo, serie, corto, corto de escuela, videoclip, encargo y videojuego. Al revés que un festival, exige que la obra ya esté estrenada (en cine, festival, TV o internet) dentro del periodo de elegibilidad. La inscripción va solo por Festhome, que cobra su propia tasa.', date '2026-10-09'),
('Fantasia (Montreal)', 'Canadá', 'Montreal', 'tier_b', 'Julio - Agosto', 'Otoño - Abril', 'Consultar bases', 'FilmFreeway', 'https://fantasiafestival.com', array['terror','ciencia_ficcion','fantasia','thriller','comedia','animacion','experimental']::text[], array['cortometraje','largometraje','documental']::text[], 84, 'Mayor festival de cine de género de Norteamérica, con fantástico, terror, acción y ciencia ficción, aunque también programa drama, documental y animación. Hay varios plazos con tarifas crecientes en FilmFreeway. Pide obras de los últimos 18 meses que no estén disponibles en línea en abierto.', date '2026-10-09'),
('Fantastic Fest (Austin)', 'Estados Unidos', 'Austin', 'tier_b', 'Septiembre', 'Enero - Mayo', '40-70 USD', 'FilmFreeway', 'https://fantasticfest.com', array['terror','ciencia_ficcion','fantasia','thriller','comedia']::text[], array['cortometraje','largometraje']::text[], 82, 'Mayor festival de género de Estados Unidos, centrado en terror, ciencia ficción y acción. Acepta largos de 70 minutos o más y cortos de menos de 25. Exige como mínimo estreno en EE. UU. (prefiere el mundial) y que la película no haya estado disponible en línea.', date '2026-10-09'),
('NIFFF (Neuchâtel International Fantastic Film Festival)', 'Suiza', 'Neuchâtel', 'tier_b', 'Julio', 'Noviembre - Abril', 'Consultar bases', 'Directo', 'https://nifff.ch', array['terror','ciencia_ficcion','fantasia','thriller','animacion']::text[], array['cortometraje','largometraje']::text[], 80, 'Principal festival fantástico suizo y miembro de la Federación Méliès, con largos (más de 60 min) y cortos (menos de 25). Exige estreno en Suiza, da prioridad a estrenos mundiales, internacionales o europeos y pide obras de los últimos 18 meses. La inscripción va por Eventival.', date '2026-10-09'),
('BIFFF (Brussels International Fantastic Film Festival)', 'Bélgica', 'Bruselas', 'tier_b', 'Marzo - Abril', 'Septiembre - Enero (cortos) / Febrero (largos)', 'Gratuito-20€', 'Festhome, FilmFreeway', 'https://www.bifff.net', array['terror','ciencia_ficcion','fantasia','thriller']::text[], array['cortometraje','largometraje']::text[], 76, 'Histórico festival fantástico europeo y calificador Méliès: su competición europea de cortos da el Méliès d''Argent, que pasa a competir por el Méliès d''Or. Los cortos de hasta 25 min cuestan unos 20€ (los belgas son gratis) y no pueden estar disponibles en abierto en internet.', date '2026-10-09'),
('Fantasporto (Oporto)', 'Portugal', 'Oporto', 'tier_b', 'Febrero - Marzo', 'Hasta noviembre', 'Gratuito', 'Directo', 'https://fantasporto.com', array['fantasia','terror','ciencia_ficcion','thriller','drama']::text[], array['cortometraje','largometraje']::text[], 74, 'Veterano festival fantástico portugués, con competición fantástica de largos y de cortos (máx. 15 min), Semana de los Realizadores para largos de cualquier género y Orient Express para cine asiático. Las películas deben ser del año en curso y estar inéditas en Portugal. Se envían gratis por email con formulario firmado.', date '2026-10-09'),
('Imagine Fantastic Film Festival (Ámsterdam)', 'Países Bajos', 'Ámsterdam', 'tier_c', 'Octubre - Noviembre', 'Primavera - Julio (cortos) / Agosto (largos)', 'Consultar bases', 'FilmFreeway', 'https://www.imaginefilmfestival.nl', array['terror','ciencia_ficcion','fantasia','thriller']::text[], array['cortometraje','largometraje']::text[], 66, 'Festival fantástico neerlandés y miembro afiliado de la Federación Méliès. Acepta largos (60 min o más) y cortos de los dos últimos años, incluso montajes en curso. Exige estreno en los Países Bajos y que la obra no esté disponible en línea.', date '2026-10-09'),
('Festival Européen du Film Fantastique de Strasbourg', 'Francia', 'Estrasburgo', 'tier_c', 'Septiembre - Octubre', 'Febrero - Junio', '20-30€', 'Festhome, FilmFreeway', 'https://strasbourgfestival.com', array['terror','ciencia_ficcion','fantasia','thriller','animacion','comedia']::text[], array['cortometraje','largometraje']::text[], 72, 'Representante francés de la Federación Méliès, con competición internacional, de animación, Made in France y Méliès d''Argent para cortos europeos (máx. 25 min), además de Midnight Shorts. Pide obras de los últimos 24 meses, y en competición los largos deben estar inéditos en Francia. Cuesta 20€ por corto y 30€ por largo.', date '2026-10-09'),
('Festival International du Film Fantastique de Gérardmer', 'Francia', 'Gérardmer', 'tier_b', 'Enero', 'Otoño - Diciembre', 'Gratuito', 'Directo', 'https://festival-gerardmer.com', array['terror','ciencia_ficcion','fantasia','thriller']::text[], array['cortometraje','largometraje']::text[], 78, 'Principal festival fantástico de Francia. Acepta largos de 75 minutos o más; en cortos solo admite ficción francesa o de mayoría francesa (máx. 30 min, sin animación ni documental). Las obras deben ser del año en curso. Los largos no pueden haberse visto en un gran evento francés y los cortos no pueden haberse emitido en TV o internet.', date '2026-10-09'),
('Trieste Science+Fiction Festival', 'Italia', 'Trieste', 'tier_c', 'Octubre - Noviembre', 'Enero - Agosto', 'Consultar bases', 'FilmFreeway', 'https://www.sciencefictionfestival.org', array['ciencia_ficcion','fantasia','terror','documental_social']::text[], array['cortometraje','largometraje','documental']::text[], 66, 'Principal festival italiano de ciencia ficción y miembro de la Federación Méliès, con el premio Asteroide (óperas primas a terceras) y el Méliès d''Argent para largos y cortos europeos (máx. 25 min). En competición exige obras inéditas en Italia y de los últimos 18 meses.', date '2026-10-09'),
('Screamfest (Los Ángeles)', 'Estados Unidos', 'Los Ángeles', 'tier_c', 'Octubre', 'Abril - Agosto', '32-82 USD', 'FilmFreeway, Directo', 'https://www.screamfestla.com', array['terror','thriller']::text[], array['cortometraje','mediometraje','largometraje']::text[], 68, 'Veterano festival de terror de Hollywood que se celebra en los TCL Chinese Theatres. Acepta supercortos, cortos, cortos largos y largos terminados el último año. Exige que no haya habido ninguna proyección pública previa en el condado de Los Ángeles y que la obra no esté distribuida ni emitida.', date '2026-10-09'),
('Fantaspoa (Porto Alegre)', 'Brasil', 'Porto Alegre', 'tier_c', 'Abril', 'Otoño - Enero', 'Consultar bases', 'FilmFreeway', 'https://fantaspoa.com', array['terror','ciencia_ficcion','fantasia','thriller']::text[], array['cortometraje','largometraje']::text[], 64, 'Mayor festival fantástico de Latinoamérica, con largos (60 min o más) y cortos (máx. 30 min) terminados en los dos últimos años. Exige que no se hayan proyectado en Porto Alegre. La inscripción va solo por FilmFreeway, sin exenciones de tasa.', date '2026-10-09'),
('Molins Horror Film Festival (Molins de Rei)', 'España', 'Molins de Rei', 'nacional', 'Noviembre', 'Febrero - Agosto (cortos) / Septiembre (largos)', '8-40€', 'Festhome, FilmFreeway', 'https://www.molinsfilmfestival.com', array['terror','thriller','comedia']::text[], array['cortometraje','largometraje']::text[], 60, 'Festival de cine de terror veterano y calificador Méliès, que entrega el Méliès d''Argent al mejor cortometraje europeo. Solo acepta terror: cortos de hasta 18 min y largos de más de 60, producidos desde enero del año anterior. Tiene sección Ç-Trencada para obras catalanas y TerrorKids.', date '2026-10-09'),
('Fancine (Festival de Cine Fantástico de Málaga)', 'España', 'Málaga', 'nacional', 'Noviembre', 'Hasta julio', '1€', 'FilmFreeway', 'https://www.fancine.org', array['fantasia','terror','ciencia_ficcion','thriller','animacion']::text[], array['cortometraje','largometraje']::text[], 55, 'Festival fantástico de la Universidad de Málaga, con competición de cortos de imagen real y de animación (máx. 15 min) por inscripción abierta en FilmFreeway, a 1€. Los largos van solo por invitación. Las obras deben ser posteriores al 1 de enero del año anterior y no haberse proyectado en la provincia de Málaga.', date '2026-10-09'),
('Karlovy Vary IFF', 'Chequia', 'Karlovy Vary', 'tier_a', 'Julio', 'Octubre-Marzo', '60-100 EUR', 'Directo', 'https://www.kviff.com', array['drama','comedia','thriller','romance','experimental','documental_social']::text[], array['largometraje','documental']::text[], 82, 'Festival FIAPF de categoría A, referencia del cine de autor en Europa Central y del Este; solo largos de más de 60 minutos. Exige estreno mundial (las bases anteriores admitían estreno internacional o europeo para ficción).', date '2026-10-09'),
('Thessaloniki IFF', 'Grecia', 'Tesalónica', 'tier_b', 'Noviembre', 'Mayo-Julio', 'Hasta 60 EUR', 'Directo', 'https://www.filmfestival.gr', array['drama','comedia','thriller','romance','experimental']::text[], array['largometraje']::text[], 72, 'Su competición internacional es para primeras y segundas películas de ficción de más de 60 minutos, producidas en los 15 meses anteriores. Exige estreno en Grecia (sin pases públicos, TV ni online en el país).', date '2026-10-09'),
('Sarajevo Film Festival', 'Bosnia y Herzegovina', 'Sarajevo', 'tier_b', 'Agosto', 'Marzo-Mayo', 'Gratuito (competición); 40 EUR otras secciones', 'Directo', 'https://www.sff.ba', array['drama','comedia','thriller','documental_social','experimental']::text[], array['largometraje','mediometraje','cortometraje','documental']::text[], 75, 'Es el principal festival y punto de encuentro de la industria del sudeste de Europa, con competiciones de largo, corto y documental. Los requisitos de estreno dependen de la sección y conviene revisarlos en las bases.', date '2026-10-09'),
('Tallinn Black Nights (PÖFF)', 'Estonia', 'Tallin', 'tier_a', 'Noviembre', 'Marzo-Agosto', 'Consultar bases', 'FilmFreeway', 'https://poff.ee', array['drama','comedia','thriller','terror','fantasia','romance','documental_social','experimental']::text[], array['largometraje','documental']::text[], 78, 'Festival FIAPF de categoría A con varias competiciones (Oficial, Primera Película, Rebels with a Cause, Doc@PÖFF). Para competir exige estreno mundial y un mínimo de 70 minutos; para otras secciones basta el estreno en Estonia.', date '2026-10-09'),
('Göteborg Film Festival', 'Suecia', 'Gotemburgo', 'tier_b', 'Enero-Febrero', 'Junio-Octubre', '35 EUR (gratuito para películas suecas)', 'Directo', 'https://goteborgfilmfestival.se', array['drama','comedia','thriller','romance','documental_social','experimental']::text[], array['largometraje','documental']::text[], 72, 'Es el gran festival nórdico y la puerta de entrada al mercado escandinavo; los largos extranjeros deben durar al menos 50 minutos y no admite cortos extranjeros. Exige estreno en Suecia y primer pase público posterior al 1 de enero del año anterior.', date '2026-10-09'),
('Shanghai IFF', 'China', 'Shanghái', 'tier_a', 'Junio', 'Diciembre-Marzo', 'Consultar bases', 'Directo', 'https://www.siff.com', array['drama','comedia','thriller','romance','animacion','documental_social']::text[], array['largometraje','cortometraje','documental']::text[], 76, 'Único festival FIAPF de categoría A de China, con los Golden Goblet en cinco categorías competitivas; buena vía hacia el mercado chino. Prefiere estrenos mundiales o internacionales y exige que la película no haya competido en otro festival FIAPF no especializado (mínimo 70 minutos en la competición principal).', date '2026-10-09'),
('Tokyo IFF', 'Japón', 'Tokio', 'tier_a', 'Octubre-Noviembre', 'Marzo-Julio', '3.300-5.500 JPY', 'Directo', 'https://www.tiff-jp.net', array['drama','comedia','thriller','romance','animacion','documental_social']::text[], array['largometraje','documental']::text[], 76, 'Es el principal festival competitivo de Japón y acepta largos de ficción, documental y animación de más de 60 minutos. Exige como mínimo estreno en Japón, con prioridad para estrenos mundiales e internacionales.', date '2026-10-09'),
('Warsaw Film Festival', 'Polonia', 'Varsovia', 'tier_b', 'Octubre', 'Abril-Julio', '30-90 USD', 'FilmFreeway, Festhome', 'https://wff.pl', array['drama','comedia','thriller','animacion','documental_social','experimental']::text[], array['largometraje','cortometraje','documental']::text[], 68, 'Festival FIAPF con competición internacional y secciones de óperas primas y documental; admite largos de más de 60 minutos y cortos de menos de 40. Exige estreno en Polonia y da prioridad a estrenos mundiales, internacionales y europeos.', date '2026-10-09'),
('Cairo IFF', 'Egipto', 'El Cairo', 'tier_b', 'Noviembre', 'Abril-Agosto', 'Consultar bases (cortos 15-30 USD)', 'Directo, FilmFreeway', 'https://www.ciff.org.eg', array['drama','comedia','thriller','romance','documental_social']::text[], array['largometraje','cortometraje','documental']::text[], 66, 'Es el festival FIAPF más veterano del mundo árabe y abre puertas a Oriente Medio y el Norte de África. La película no puede haberse proyectado en la región MENA ni emitido en TV o internet antes de su pase en El Cairo.', date '2026-10-09'),
('Red Sea IFF (Yeda)', 'Arabia Saudí', 'Yeda', 'tier_b', 'Diciembre', 'Mayo-Agosto', 'Consultar bases', 'Directo', 'https://redseafilmfest.com', array['drama','comedia','thriller','animacion','documental_social']::text[], array['largometraje','cortometraje','documental']::text[], 68, 'Sus competiciones están reservadas a cineastas árabes, asiáticos y africanos (residentes en cualquier país) y cuenta con un fuerte fondo y mercado. La película no puede haber estado disponible en TV, internet ni plataformas en la región MENA.', date '2026-10-09'),
('Marrakech IFF', 'Marruecos', 'Marrakech', 'tier_b', 'Noviembre-Diciembre', 'Abril-Julio', 'Consultar bases', 'Directo', 'https://marrakech-festival.com', array['drama','comedia','thriller','romance']::text[], array['largometraje']::text[], 70, 'Su competición reúne unas 12 primeras y segundas películas de ficción internacionales ante jurados de gran prestigio. En la edición anterior se exigía como mínimo estreno africano.', date '2026-10-09'),
('Palm Springs IFF', 'Estados Unidos', 'Palm Springs', 'tier_b', 'Enero', 'Mayo-Agosto', 'Consultar bases', 'FilmFreeway', 'https://www.psfilmfest.org', array['drama','comedia','thriller','romance','documental_social']::text[], array['largometraje','documental']::text[], 65, 'Es un escaparate clave del cine internacional en EE. UU., sobre todo para candidatas al Óscar a mejor película internacional; solo largos de 70 minutos o más. No exige estreno mundial, pero la película no puede haberse visto en el Valle de Coachella ni en streaming en EE. UU.', date '2026-10-09'),
('SXSW Film & TV Festival (Austin)', 'Estados Unidos', 'Austin', 'tier_b', 'Marzo', 'Julio-Octubre', '95-125 USD (largos); 55-90 USD (cortos)', 'Directo', 'https://www.sxsw.com/film', array['drama','comedia','thriller','terror','ciencia_ficcion','animacion','documental_social','experimental']::text[], array['largometraje','cortometraje','documental']::text[], 78, 'Es el gran escaparate del cine independiente y de género en EE. UU., con mucha presencia de prensa y compradores. El estado de estreno pesa en la selección, pero no es un requisito absoluto; la película no puede haberse estrenado en plataformas online.', date '2026-10-09'),
('Telluride Film Festival', 'Estados Unidos', 'Telluride', 'tier_b', 'Septiembre', 'Abril-Julio', '35-95 USD', 'Directo', 'https://www.telluridefilmfestival.org', array['drama','comedia','biopic','documental_social','experimental']::text[], array['largometraje','cortometraje','documental']::text[], 88, 'Es un festival muy selectivo y decisivo para la temporada de premios en EE. UU.; su programa no se anuncia hasta la víspera. Los largos deben tener allí su primer pase en Norteamérica y solo admite montajes con imagen cerrada.', date '2026-10-09'),
('Seattle IFF (SIFF)', 'Estados Unidos', 'Seattle', 'tier_c', 'Mayo', 'Agosto-Enero', 'Consultar bases', 'FilmFreeway', 'https://www.siff.net', array['drama','comedia','thriller','animacion','documental_social','experimental']::text[], array['largometraje','cortometraje','documental']::text[], 60, 'Es uno de los festivales de público más grandes de EE. UU. y una buena plataforma para el lanzamiento en ese país. Basta con un estreno en el oeste del estado de Washington y admite películas ya vistas en otros festivales de EE. UU.', date '2026-10-09'),
('BFI London Film Festival', 'Reino Unido', 'Londres', 'tier_b', 'Octubre', 'Marzo-Mayo', 'Consultar bases', 'Directo', 'https://www.bfi.org.uk/london-film-festival', array['drama','comedia','thriller','terror','documental_social','experimental','animacion']::text[], array['largometraje','cortometraje','documental']::text[], 82, 'Es el gran escaparate del cine de autor internacional en Reino Unido. La convocatoria abierta de 2026 se limitó a obras de Reino Unido e Irlanda, así que el cine internacional entra sobre todo por invitación de los programadores.', date '2026-10-09'),
('Edinburgh IFF', 'Reino Unido', 'Edimburgo', 'tier_b', 'Agosto', 'Diciembre-Abril', '55-125 USD', 'FilmFreeway', 'https://www.edfilmfest.org', array['drama','comedia','thriller','terror','animacion','documental_social','experimental']::text[], array['largometraje','cortometraje','documental']::text[], 66, 'Es uno de los festivales en activo más antiguos del mundo y ofrece el Sean Connery Prize, dotado con 50.000 libras. Exige como mínimo estreno en Reino Unido, y estreno mundial para optar a los premios.', date '2026-10-09'),
('Zurich Film Festival', 'Suiza', 'Zúrich', 'tier_b', 'Septiembre-Octubre', 'Marzo-Junio', 'Consultar bases', 'FilmFreeway', 'https://zff.com', array['drama','comedia','thriller','romance','documental_social']::text[], array['largometraje','documental']::text[], 70, 'Sus competiciones internacionales de ficción y documental son para la primera, segunda o tercera película de un director (mínimo 60 minutos). Exige como mínimo estreno en Suiza.', date '2026-10-09'),
('FilmFestival Cottbus', 'Alemania', 'Cottbus', 'tier_c', 'Noviembre', 'Abril-Julio', 'Consultar bases', 'FilmFreeway', 'https://www.filmfestivalcottbus.de', array['drama','comedia','thriller','documental_social','experimental']::text[], array['largometraje','cortometraje']::text[], 55, 'Es el festival de referencia del cine de Europa del Este, Centro-Este y Sudeste (también Grecia, Turquía, Finlandia, el Cáucaso y Asia Central); no admite producciones españolas salvo coproducción con esos países. La competición de largos exige estreno en Alemania.', date '2026-10-09'),
('Transilvania IFF (Cluj)', 'Rumanía', 'Cluj-Napoca', 'tier_b', 'Junio', 'Octubre-Febrero', '30-50 EUR', 'Directo', 'https://tiff.ro', array['drama','comedia','thriller','terror','fantasia','documental_social','experimental']::text[], array['largometraje','documental']::text[], 64, 'Es el principal festival de Rumanía; su Competición Oficial es para primeras y segundas películas de ficción y la sección What''s Up, Doc? para documentales. La película no puede haberse proyectado en Rumanía y su estreno mundial debe ser reciente (posterior a mayo del año anterior).', date '2026-10-09'),
('Sofia IFF', 'Bulgaria', 'Sofía', 'tier_c', 'Marzo', 'Septiembre-Octubre', '35-45 EUR', 'Directo', 'https://siff.bg', array['drama','comedia','thriller','documental_social']::text[], array['largometraje','documental']::text[], 56, 'Es el mayor festival competitivo de Bulgaria (acreditado por la FIAPF), con competiciones internacional de primeras y segundas películas, balcánica y documental. Las bases publicadas no detallan requisitos de estreno, así que conviene consultarlos.', date '2026-10-09'),
('Film Fest Gent', 'Bélgica', 'Gante', 'tier_b', 'Octubre', 'Marzo-Julio', 'Consultar bases', 'Directo', 'https://www.filmfestival.be', array['drama','comedia','musical','romance','documental_social']::text[], array['largometraje','mediometraje','cortometraje']::text[], 62, 'Festival belga de referencia, centrado en el impacto de la música en el cine, con una competición de 12 a 15 largos. Exige como mínimo estreno en Bélgica.', date '2026-10-09'),
('Viennale', 'Austria', 'Viena', 'tier_b', 'Octubre-Noviembre', 'Abril-Julio', 'Consultar bases', 'Directo', 'https://www.viennale.at', array['drama','comedia','experimental','documental_social','noir']::text[], array['largometraje','mediometraje','cortometraje','documental']::text[], 72, 'Es un festival no competitivo de cine de autor, muy respetado por la crítica, sin límites de duración; el formulario de inscripción abre en abril y la mayoría de películas se seleccionan por invitación. Exige estreno en Austria para todo el cine contemporáneo.', date '2026-10-09'),
('Torino Film Festival', 'Italia', 'Turín', 'tier_b', 'Noviembre-Diciembre', 'Mayo-Septiembre', '15-30 EUR (más caro desde agosto)', 'FilmFreeway', 'https://www.torinofilmfest.org', array['drama','comedia','thriller','terror','documental_social','experimental']::text[], array['largometraje','cortometraje','documental']::text[], 68, 'Es un festival italiano de cine joven e independiente con competiciones internacionales de largo, documental y corto. Los largos requieren estreno mundial o internacional, y los cortos estreno internacional o europeo.', date '2026-10-09'),
('Rome Film Fest (Festa del Cinema di Roma)', 'Italia', 'Roma', 'tier_b', 'Octubre', 'Abril-Julio', '60-150 EUR', 'Directo', 'https://www.romacinemafest.it', array['drama','comedia','thriller','animacion','documental_social']::text[], array['largometraje','documental']::text[], 68, 'En su competición Progressive Cinema (máximo 18 títulos) compiten juntos ficción, documental y animación; tiene gran eco mediático en Italia. Da prioridad a los estrenos internacionales.', date '2026-10-09'),
('Mostra Internazionale del Nuovo Cinema (Pesaro)', 'Italia', 'Pesaro', 'tier_c', 'Junio', 'Febrero-Abril', 'Consultar bases', 'Directo', 'https://pesarofilmfest.it', array['experimental','drama','documental_social']::text[], array['largometraje','mediometraje','cortometraje','documental']::text[], 58, 'Es un festival histórico de nuevo cine y lenguajes de vanguardia; su Concorso Pesaro Nuovo Cinema no pone límites de formato, género, duración ni idioma. El requisito de estreno no aparece publicado, así que conviene consultarlo en las bases.', date '2026-10-09'),
('Les Arcs Film Festival', 'Francia', 'Bourg-Saint-Maurice (Les Arcs)', 'tier_b', 'Diciembre', 'Junio-Agosto', '25-45 EUR', 'Directo', 'https://www.lesarcs-filmfest.com', array['drama','comedia','thriller','animacion','documental_social']::text[], array['largometraje','cortometraje','documental']::text[], 62, 'Es un festival de cine europeo (la productora principal debe tener sede en Europa) que se celebra junto al Industry Village, con su Coproduction Village y sus Work in Progress. Exige estreno en Francia, aunque algunos listados hablan de estreno mundial, así que conviene confirmarlo en las bases.', date '2026-10-09'),
('Premiers Plans (Angers)', 'Francia', 'Angers', 'tier_b', 'Enero', 'Junio-Septiembre', '7-30 EUR', 'Directo', 'https://www.premiersplans.org', array['drama','comedia','animacion','documental_social']::text[], array['largometraje','cortometraje','documental']::text[], 64, 'Es el festival de referencia para primeras y segundas películas europeas (largos de más de 59 minutos, cortos, cine de escuela y animación) y muy influyente en la distribución francesa. La película no puede haberse distribuido comercialmente ni emitido en Francia.', date '2026-10-09'),
('IFF Mannheim-Heidelberg', 'Alemania', 'Mannheim y Heidelberg', 'tier_c', 'Noviembre', 'Marzo-Junio', '25-40 EUR', 'Directo', 'https://www.iffmh.de', array['drama','comedia','thriller']::text[], array['largometraje']::text[], 56, 'Su competición On the Rise es para primeras y segundas películas de más de 61 minutos y es un festival veterano en el descubrimiento de nuevos autores. Exige estreno en Alemania, con prioridad para estrenos europeos o internacionales y un estreno mundial reciente.', date '2026-10-09'),
('Molodist Kyiv IFF', 'Ucrania', 'Kiev', 'tier_c', 'Octubre-Noviembre', 'Enero-Agosto', 'Consultar bases', 'FilmFreeway', 'https://molodist.com', array['drama','comedia','animacion','documental_social','experimental']::text[], array['largometraje','cortometraje','documental']::text[], 54, 'Es el principal festival de Ucrania, acreditado por la FIAPF, con competiciones de largo, corto y cine de escuela. La película no puede haberse proyectado antes en Ucrania y debe llevar subtítulos en inglés.', date '2026-10-09'),
('Jerusalem Film Festival', 'Israel', 'Jerusalén', 'tier_b', 'Julio', 'Enero-Abril', 'Consultar bases', 'Directo', 'https://www.jff.org.il', array['drama','comedia','documental_social']::text[], array['largometraje','documental']::text[], 60, 'Es el principal festival internacional de Israel y solo admite largos de más de 60 minutos. Exige estreno en Israel, y la película no puede haberse mostrado en ningún lugar más de 12 meses antes del festival.', date '2026-10-09'),
('European Film Market (Berlín)', 'Alemania', 'Berlín', 'tier_b', 'Febrero', 'Octubre-Febrero', 'Consultar bases', 'Directo', 'https://www.efm-berlinale.de', array['drama','comedia','thriller','terror','animacion','documental_social','otro']::text[], array['largometraje','documental']::text[], 88, 'Es el primer gran mercado del año, junto a la Berlinale, y sirve para vender la película a agentes de ventas y distribuidores, buscar coproducción y organizar pases de mercado. Funciona con acreditación de pago con tarifas Early Bear, Regular y Late (desde octubre); no exige estreno.', date '2026-10-09'),
('Marché du Film (Cannes)', 'Francia', 'Cannes', 'tier_b', 'Mayo', 'Febrero-Abril', 'Consultar bases (badge aprox. 530-630 EUR sin IVA en 2026)', 'Directo', 'https://www.marchedufilm.com', array['drama','comedia','thriller','terror','animacion','documental_social','otro']::text[], array['largometraje','documental']::text[], 88, 'Es el mayor mercado de cine del mundo, durante el Festival de Cannes, y sirve para ventas internacionales, búsqueda de financiación y coproducción, pases de mercado y programas como Producers Network o Cannes Docs. La acreditación se tramita de febrero a mediados de abril, con recargo para las solicitudes tardías.', date '2026-10-09'),
('American Film Market (AFM, Los Ángeles)', 'Estados Unidos', 'Los Ángeles', 'tier_b', 'Noviembre', 'Marzo-Noviembre', '345-1.295 USD (badges de asistente)', 'Directo', 'https://americanfilmmarket.com', array['thriller','terror','comedia','drama','aventura','ciencia_ficcion','otro']::text[], array['largometraje']::text[], 80, 'Es el gran mercado de cine independiente de EE. UU., centrado en adquisiciones, financiación y ventas, especialmente de cine comercial y de género. La inscripción de expositores abre en marzo-abril y la de asistentes en junio; no exige estreno.', date '2026-10-09'),
('Thessaloniki Agora (TIFF Agora)', 'Grecia', 'Tesalónica', 'tier_b', 'Noviembre', 'Consultar bases', 'Consultar bases', 'Directo', 'https://www.filmfestival.gr/en/tiff/tiff-agora/', array['drama','comedia','thriller','documental_social']::text[], array['largometraje']::text[], 62, 'Es el mercado del Festival de Tesalónica, centrado en el sudeste de Europa y el Mediterráneo, y sirve para buscar coproductores (Crossroads Co-production Forum, para ficción en desarrollo), presentar películas en postproducción (Works in Progress) y vender a través de una videoteca online en Cinando.', date '2026-10-09')
) as v(name, country, city, tier, month, deadline, submission_fee, platform, url, genres, accepts_types, prestige, reason, last_verified_at)
where not exists (select 1 from festivals f where lower(f.name) = lower(v.name));
